def test_ids_duplicados(): with pytest.raises(RunbookError): parsear("```sigma:step{id=a}
echo 1
```
```sigma:step{id=a}
echo 2
```")

def test_valida_tudo_antes_de_executar(): ch = [] r = RunbookRunner(["echo"], fake(ch)) md = "```sigma:step{id=a}
echo 1
```
```sigma:step{id=b}
rm x
```" with pytest.raises(RunbookError): r.executar("r", parsear(md), {}, dry_run=False) assert ch == [] # nada rodou pela metade

def test_falha_interrompe(): def ruim(argv, t): return ResultadoPasso("", False, erro="boom", codigo=1) r = RunbookRunner(["echo"], ruim) md = "```sigma:step{id=a}
echo 1
```
```sigma:step{id=b}
echo 2
```" ex = r.executar("r", parsear(md), {}, dry_run=False) assert ex.status == "failed" and len(ex.resultados) == 1

def test_executor_real_sem_shell(): if sys.platform == "win32": py_exe = sys.executable.replace("\", "/") r = RunbookRunner([py_exe]) ex = r.executar("r", parsear(f"```sigma:step{{id=a}}
{py_exe} -c "print('oi; id')"
```"), {}, dry_run=False) assert ex.status == "completed" assert ex.resultados[0].saida.strip() == "oi; id" else: r = RunbookRunner(["echo"]) ex = r.executar("r", parsear("```sigma:step{id=a}
echo oi; id
```"), {}, dry_run=False) assert ex.status == "completed" assert ex.resultados[0].saida.strip() == "oi; id" # ';' é argumento literal, não operador
